   {
    "quote": "Prevent UPDATE and DELETE logical replication operations on tables where the subscription owner does not have SELECT permission on the table",
    "source": "PostgreSQL 15 release notes: Migration to Version 15",
    "release_of_change": "15"
   }
  ]
 },
